UPDATE articulos SET metadata = '{"areas": ["creatividad", "sociabilidad"], "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "cantidad": "04 participantes", "duracion": "20 minutos", "unidades": ["manada", "compañía", "tropa"], "objetivos": ["Estimular la creatividad", "Fomentar la comunicación e interpretación", "Trabajo en equipo", "Crear un ambiente de distensión"], "materiales": ["Ninguno"], "variaciones": "<b>Historia Atroz con Efectos de Sonido:</b> Una patrulla actúa mientras otra realiza la banda sonora y ruidos ambientales en vivo.<br><b>Historia Atroz en Reversa:</b> Representar la trama comenzando por el desenlace dramático hasta llegar al inicio cómico.<br><b>Edición Leyendas Nua Mana:</b> Recrear pasajes humorísticos basados en anécdotas reales del Grupo Scout.", "recomendaciones": "Mantener un ritmo fluido en la narración sin pausas prolongadas. Promover un ambiente festivo donde se valore la audacia escénica.", "justificacion_areas": "La Drama-Comedia de la Historia Atroz potencia la creatividad al exigir la improvisación inmediata de roles dramáticos, gestos cómicos y expresión corporal. Desarrolla la sociabilidad al afianzar la desinhibición social, el juego cooperativo sin juicio y el espíritu festivo en la unidad.", "objetivos_educativos": [{"id": "52b5580a-7d0f-454f-b2ae-0d3318129165", "area": "Creatividad", "unidad": "Manada", "texto": "Canto, bailo y preparo actuaciones con mis amigos de la Manada.", "como_se_cumple": "Participando con alegría y soltura en la dramatización cómica del cuento narrado."}, {"id": "14b82459-ac31-4496-a875-8e9bd5666030", "area": "Creatividad", "unidad": "Manada", "texto": "En las actividades que hago se nota lo que pienso y siento.", "como_se_cumple": "Expresando emociones y caracterizaciones teatrales exageradas ante la unidad."}, {"id": "d581cfa7-db1f-4b08-b4d3-525b23e418ea", "area": "Creatividad", "unidad": "Compañía", "texto": "Participo con entusiasmo en las actividades artísticas de mi Compañía.", "como_se_cumple": "Improvisando escenas dramáticas y personajes cómicos al ritmo de la historia."}, {"id": "0136350b-c2b2-429f-8feb-2fdc57e29b8b", "area": "Creatividad", "unidad": "Compañía", "texto": "Me gusta cantar y conozco muchas canciones.", "como_se_cumple": "Aportando expresiones vocales, efectos sonoros y canciones en la actuación de patrulla."}, {"id": "39eaf1aa-f703-4fd0-a4b3-b9756dc30539", "area": "Creatividad", "unidad": "Tropa", "texto": "Participo con entusiasmo en las actividades artísticas de mi Tropa.", "como_se_cumple": "Desarrollando audacia escénica y actuación colectiva en la Tropa."}, {"id": "6e910d1c-7021-49a5-9ece-637f480a1ec7", "area": "Creatividad", "unidad": "Tropa", "texto": "Expreso por distintos medios mis intereses y aptitudes artísticas.", "como_se_cumple": "Demonstrando iniciativa y talento expresivo en la caracterización de personajes."}, {"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "unidad": "Manada", "como_se_cumple": "Acatando los roles asignados en el relato sin vacilaciones."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "unidad": "Manada", "como_se_cumple": "Participando con alegría y respeto en las representaciones grupales."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Compañía", "como_se_cumple": "Construyendo un clima libre de burlas que incentive la participación de todas."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Compañía", "como_se_cumple": "Apoyando con aplausos el desempeño escénico de las compañeras de unidad."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "texto": "Conozco y respeto las principales normas de convivencia.", "unidad": "Tropa", "como_se_cumple": "Fomentando el compañerismo y la confianza mutua en presentaciones de fogata."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "unidad": "Tropa", "como_se_cumple": "Afianzando la cohesión e integración entre las distintas patrullas."}]}'::jsonb WHERE slug = 'la-drama-comedia-de-la-historia-atroz';
DELETE FROM articulo_objetivos_educativos WHERE articulo_id = (SELECT id FROM articulos WHERE slug = 'la-drama-comedia-de-la-historia-atroz');
UPDATE articulos SET metadata = '{"areas": ["creatividad", "corporalidad"], "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "cantidad": "04 participantes", "duracion": "20 minutos", "unidades": ["manada", "compañía", "tropa"], "objetivos": ["Estimular la creatividad", "Reforzar la coordinación al interior del equipo", "Estimular la agilidad mental", "Crear un clima de pertenencia"], "materiales": ["Ninguno"], "variaciones": "<b>Geometría Espacial a Oscuras:</b> Armar las figuras en silencio utilizando únicamente el tacto en el piso de campamento.<br><b>Geometría Dinámica:</b> Las figuras deben desplazarse 5 metros en el plano sin deformar los lados geométricos.<br><b>Símbolos Scouts en 3D:</b> Formar la Flor de Lis o el Trébol WAGGGS con la totalidad de la unidad.", "recomendaciones": "Revisar que la superficie esté despejada. Fomentar la comunicación tranquila y la distribución eficiente del espacio entre seisenas.", "justificacion_areas": "La Geometría Espacial Colectiva potencia la creatividad al requerir la resolución ingeniosa de rompecabezas anatómicos en 3D. Desarrolla la corporalidad al ejercitar la propiocepción, la elasticidad, el equilibrio postural y la coordinación kinésica entre pares.", "objetivos_educativos": [{"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando el plano espacial para acomodar el cuerpo en la posición geométrica requerida."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Resolviendo velozmente la distribución de vértices y lados en el equipo."}, {"id": "12686e7d-d6af-4c74-928d-c859d5b883d5", "area": "Creatividad", "unidad": "Compañía", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Proponiendo soluciones tácticas para armar los ángulos de la figura."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Visualizando el resultado geométrico desde la perspectiva del observador externo."}, {"id": "e465926e-deed-4341-956f-047f56860e5e", "area": "Creatividad", "unidad": "Tropa", "texto": "Ayudo en la preparación de los temas que discutimos en mi patrulla.", "como_se_cumple": "Coordinando con dinamismo las posiciones espaciales de la patrulla."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando abstracciones tridimensionales mediante el alineamiento corporal."}, {"id": "d9ebcd96-c9cf-444f-94fb-5569110a1b99", "area": "Corporalidad", "texto": "Participo en actividades que me ayudan a tener un cuerpo cada vez más fuerte, ágil, veloz y flexible.", "unidad": "Manada", "como_se_cumple": "Estirando y flexionando extremidades para moldear las líneas de la figura geométrica."}, {"id": "626a313e-0407-4cfd-b714-c6aa6e51738c", "area": "Corporalidad", "texto": "Manejo cada vez mejor mis brazos, piernas, manos y pies.", "unidad": "Manada", "como_se_cumple": "Afinando la postura de brazos y piernas para mantener la figura estable."}, {"id": "273f60b8-7953-4416-97c3-e8c83615364f", "area": "Corporalidad", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "unidad": "Compañía", "como_se_cumple": "Ejercitando el equilibrio tónico y la resistencia en alineaciones grupales."}, {"id": "91473f71-9345-4bcf-bfc7-dea709d12361", "area": "Corporalidad", "texto": "Respeto mi cuerpo y el de los demás.", "unidad": "Compañía", "como_se_cumple": "Respetando la postura y límites físicos de las compañeras al entrelazar brazos."}, {"id": "5c9843d1-39fd-4298-870c-5e46f29ffbf6", "area": "Corporalidad", "texto": "Participo en actividades que me ayudan a mantener mi cuerpo fuerte y sano.", "unidad": "Tropa", "como_se_cumple": "Perfeccionando el control psicomotriz y la postura en equipo."}, {"id": "fb56310a-a9cf-46e3-9c34-c4643f6b9035", "area": "Corporalidad", "texto": "Respeto mi cuerpo y el de los demás.", "unidad": "Tropa", "como_se_cumple": "Fomentando el cuidado y la alineación armónica del grupo en el espacio."}]}'::jsonb WHERE slug = 'la-geometria-espacial-colectiva';
DELETE FROM articulo_objetivos_educativos WHERE articulo_id = (SELECT id FROM articulos WHERE slug = 'la-geometria-espacial-colectiva');
COMMIT;